import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';

/// Firebase configuration for MONMON.
/// This uses explicit Firebase options so the app does not depend on
/// Android resources generated by the google-services Gradle plugin.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError(
        'MONMON is configured for Android. Web Firebase configuration is not included.',
      );
    }

    if (defaultTargetPlatform == TargetPlatform.android) {
      return android;
    }

    throw UnsupportedError(
      'DefaultFirebaseOptions are not configured for this platform.',
    );
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyBSf09dBHtlAaFsFzKU5bCVNhW6WZv1aZ0',
    appId: '1:13450233483:android:6b86cd82e7088d77e9768e',
    messagingSenderId: '13450233483',
    projectId: 'monmon-app-40cdd',
    storageBucket: 'monmon-app-40cdd.firebasestorage.app',
  );
}
